class Solution {
  private static final long NEG = Long.MIN_VALUE / 4;
  private long[] sum, pref, suf, best;

  private void pull(int i) {
    int l = 2 * i, r = 2 * i + 1;
    sum[i] = sum[l] + sum[r];
    pref[i] = Math.max(pref[l], sum[l] + pref[r]);
    suf[i] = Math.max(suf[r], sum[r] + suf[l]);
    best[i] = Math.max(Math.max(best[l], best[r]), suf[l] + pref[r]);
  }

  private void set(int size, int pos, boolean present, long v) {
    int i = size + pos;
    if (present) {
      sum[i] = v;
      pref[i] = suf[i] = best[i] = v;
    } else {
      sum[i] = 0;
      pref[i] = suf[i] = best[i] = NEG;
    }
    for (i >>= 1; i >= 1; i >>= 1) pull(i);
  }

  public long maxSubarraySum(int[] nums) {
    int n = nums.length, size = 1;
    while (size < n) size <<= 1;
    sum = new long[2 * size];
    pref = new long[2 * size];
    suf = new long[2 * size];
    best = new long[2 * size];
    for (int i = 0; i < size; i++) {
      if (i < n) {
        sum[size + i] = nums[i];
        pref[size + i] = suf[size + i] = best[size + i] = nums[i];
      } else {
        pref[size + i] = suf[size + i] = best[size + i] = NEG;
      }
    }
    for (int i = size - 1; i >= 1; i--) pull(i);
    long ans = best[1];
    long[] keys = new long[n];
    for (int i = 0; i < n; i++) keys[i] = ((long) (nums[i] + 1_000_000) << 20) | i;
    java.util.Arrays.sort(keys);
    for (int i = 0; i < n; ) {
      int j = i;
      while (j < n && (keys[j] >> 20) == (keys[i] >> 20)) j++;
      if (j - i < n) {
        for (int t = i; t < j; t++) set(size, (int) (keys[t] & ((1 << 20) - 1)), false, 0);
        ans = Math.max(ans, best[1]);
        for (int t = i; t < j; t++) {
          int pos = (int) (keys[t] & ((1 << 20) - 1));
          set(size, pos, true, nums[pos]);
        }
      }
      i = j;
    }
    return ans;
  }
}
